59	void d13x_start(uint32_t mhartid)
60	{
61	  uint8_t *dest;
62	
63	  /* The E907 implements an FPU; let the common RISC-V code configure it. */
64	
65	  riscv_fpuconfig();
66	
67	  /* The contest bring-up is single-hart only. Hold any unexpected hart. */
68	
69	  if (mhartid != 0)
70	    {
71	      for (;;)
72	        {
73	          asm volatile ("wfi");
74	        }
75	    }
76	
77	  /* Images are loaded directly into SRAM, so only .bss needs clearing here. */
78	
79	#ifndef CONFIG_ARCH_SKIP_ZERO_BSS
80	  for (dest = _sbss; dest < _ebss; )
81	    {
82	      *dest++ = 0;
83	    }
84	#endif
85	
86	#ifdef USE_EARLYSERIALINIT
87	  riscv_earlyserialinit();
88	#endif
89	
90	  d13x_chip_early_boot();
91	
92	  nx_start();
93	
94	  for (;;)
95	    {
96	      asm volatile ("wfi");
97	    }
98	}
