2	ENTRY(__start)
3	
4	D13X_SRAM_BASE = 0x30040000;
5	D13X_SRAM_RESERVED = 0x4000;
6	D13X_SRAM_LENGTH = 0x100000 - D13X_SRAM_RESERVED;
7	
8	MEMORY
9	{
10	    sram (rwx) : ORIGIN = D13X_SRAM_BASE + D13X_SRAM_RESERVED,
11	                 LENGTH = D13X_SRAM_LENGTH
12	}
13	
14	SECTIONS
15	{
16	    .text : {
17	        _stext = .;
18	        *(.text.entry)
19	        *(.text .text.*)
20	        *(.rodata .rodata.*)
21	        *(.srodata .srodata.*)
22	        . = ALIGN(4);
23	        _sinit = ABSOLUTE(.);
24	        *(.init)
25	        *(.fini)
26	        KEEP(*(SORT_BY_INIT_PRIORITY(.init_array.*)))
27	        KEEP(*(.init_array))
28	        KEEP(*(.fini_array))
29	        . = ALIGN(4);
30	        _etext = .;
31	        _eronly = .;
32	    } > sram
33	
34	    .data : {
35	        _sdata = .;
36	        PROVIDE(__global_pointer$ = . + 0x800);
37	        *(.data .data.*)
38	        *(.sdata .sdata.*)
39	        . = ALIGN(4);
40	        _edata = .;
41	    } > sram
42	
43	    .bss (NOLOAD) : {
44	        _sbss = .;
45	        *(.bss .bss.*)
46	        *(.sbss .sbss.*)
47	        *(COMMON)
48	        . = ALIGN(4);
49	        _ebss = .;
50	    } > sram
51	
52	    .stack (NOLOAD) : {
53	        . = ALIGN(16);
54	        . = . + 8192;
55	        . = ALIGN(16);
56	        _estack = .;
57	    } > sram
58	
59	    .heap (NOLOAD) : {
60	        . = ALIGN(16);
61	        _sheap = .;
62	        _eheap = ORIGIN(sram) + LENGTH(sram);
63	    } > sram
64	}
